    private static readonly Dictionary<string, Texture2D> Cache = [];
    public static Texture2D? Texture(string id)
    {
        if (!Paths.TryGetValue(id, out string? path)) return null;
        if (Cache.TryGetValue(id, out var cached)) return cached;
        using var image = new Image();
        string svg = "<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200' viewBox='0 0 100 100'><path d='" + path
            + "' fill='none' stroke='#e0c68c' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/></svg>";
        if (image.LoadSvgFromString(svg) != Error.Ok) throw new InvalidDataException("商品图标无法解析：" + id);
        return Cache[id] = ImageTexture.CreateFromImage(image);
    }
